        "Trainline（トレインライン）、Omio（オミオ）：ヨーロッパの鉄道やバスを、まとめて探せます。予約手数料がかかることがあります。",
        "Citymapper（シティマッパー）、Google マップ：街なかの乗り換えに使えます。",
