        "空港バスは、A11系統がセントラルや湾仔へ、A21系統が尖沙咀へ行きます。15〜30分おきです。深夜は、Nの付くナイトバスが走っています。",
        "到着ロビーを出て、「To City（往市區）」の案内に従うと、バスの乗り場に行けます。",
